        getCMCDirectLink: function (book, ch) {
            const chNum = parseInt(ch, 10) || 1;
            const bookMap = this.CMC_DIRECT_URLS[book];
            if (bookMap && bookMap[chNum]) return bookMap[chNum];
            return this.getCMCSearchLink(book, chNum);
        },

        getVolumeLink: function (book) {
            const info = this.bookMap[book];
            return info && info.ot ? CMC_OT : CMC_NT;
        },

        getChapterCount: function (book) {
            const info = this.bookMap[book];
            return (info && info.ch) || 50;
        },

        getFHLLink: function (book, ch) {
            const info = this.bookMap[book];
            const bid = info ? info.id : 1;
            return 'https://bible.fhl.net/new/read.php?id=' + bid + '&chp=' + (ch || 1);
        },

